insert into public.preparation_guides as g
  (key, name, section, system, organ, tissue, stain, difficulty, low_magnification, high_magnification, steps, features, inclusions, differential, mistakes, structures, sources)
values
  ('cytology-mitosis', 'Митоз', '1. Цитология', 'Цитология', 'Клетка', 'Клеточный уровень', 'Гематоксилин-эозин', 1, 'Искать делящиеся клетки с видимыми хромосомами на разных стадиях', 'Стадии митоза: профаза, метафаза, анафаза, телофаза', '["Начать с малого увеличения и найти участок с плотно расположенными делящимися клетками.","Найти клетки с тёмными конденсированными хромосомами — это фигуры митоза.","Перейти на большое увеличение и определить стадии: профаза, метафаза, анафаза, телофаза.","В метафазе хромосомы выстроены по экватору, в анафазе расходятся к полюсам.","Сравнить с интерфазными ядрами рядом: там хромосомы не видны."]'::jsonb, '["Хромосомы в разных стадиях конденсации","Веретено деления","Материнская клетка","Дочерние клетки"]'::jsonb, '["Хромосомы","Ядерная оболочка (разрушается/восстанавливается)"]'::jsonb, '["Не путать с интерфазными клетками — в митозе хромосомы конденсированы и видимы"]'::jsonb, '["Принимать пикнотичные ядра за хромосомы"]'::jsonb, ARRAY['mitotic-figures', 'chromosomes', 'nucleus']::text[], '[]'::jsonb),
  ('cytology-fat-inclusions', 'Жировые включения', '1. Цитология', 'Цитология', 'Клетка (печень)', 'Клеточный уровень', 'Судан III / Осмиевая кислота', 1, 'Найти клетки с оптически пустыми вакуолями (жир растворяется при проводке)', 'Крупные оптически пустые вакуоли в цитоплазме', '["Малое увеличение: найти светлые округлые вакуоли в цитоплазме гепатоцитов.","Обратить внимание, что вакуоли не окрашены — жир вымывается при проводке.","Большое увеличение: оценить размер и количество включений в клетке.","Найти ядро, оттеснённое крупной жировой каплей к периферии.","Не путать с оптически пустыми пространствами между клетками."]'::jsonb, '["Оптически пустые вакуоли","Крупные капли жира в цитоплазме гепатоцитов","Ядро оттеснено к периферии"]'::jsonb, '["Жировые капли","Липидные включения"]'::jsonb, '["Отличить от гликогена — жировые включения выглядят как пустые вакуоли, гликоген окрашивается PAS-реакцией"]'::jsonb, '["Принимать артефакты за жировые включения"]'::jsonb, ARRAY['fat-droplets', 'nucleus']::text[], '[]'::jsonb),
  ('embryology-egg', 'Яйцеклетка', '2. Эмбриология', 'Эмбриология', 'Яичник', 'Половые клетки', 'Гематоксилин-эозин', 1, 'Найти крупные клетки в корковом веществе яичника', 'Строение овоцита: ядро, ядрышко, цитоплазма, блестящая оболочка', '["Найти крупную округлую клетку с большим светлым ядром.","Определить блестящую зону вокруг цитоплазмы.","Оценить фолликулярные клетки вокруг (лучистый венец), если они сохранены.","Проверить, что цитоплазма гомогенная, без крупных включений."]'::jsonb, '["Крупная клетка","Крупное ядро","Ядрышко","Цитоплазма с желтком"]'::jsonb, '["Желточные включения","Кортикальные гранулы"]'::jsonb, '["Яйцеклетка крупнее всех окружающих клеток, имеет чёткое ядро"]'::jsonb, '["Принимать крупные клетки атретических фолликулов за нормальные яйцеклетки"]'::jsonb, ARRAY['oocyte', 'zona-pellucida', 'nucleus']::text[], '[]'::jsonb),
  ('embryology-sperm', 'Сперматозоид', '2. Эмбриология', 'Эмбриология', 'Семенник', 'Половые клетки', 'Гематоксилин-эозин', 1, 'Найти извитые семенные канальцы в семеннике', 'Головка, шейка, хвост сперматозоида', '["Малое увеличение: найти скопления мелких вытянутых клеток.","Большое увеличение: выделить головку, шейку и хвост.","Оценить форму головки и наличие акросомы (тёмный колпачок).","Обратить внимание на извитость хвоста — признак живых клеток."]'::jsonb, '["Головка с акросомой","Ядро","Хвост"]'::jsonb, '["Акросома (гранулы)","Митохондрии в шейке"]'::jsonb, '["Сперматозоид — самая маленькая клетка препарата, легко отличима по хвосту"]'::jsonb, '["Путать с ресничками эпителия"]'::jsonb, ARRAY['spermatozoa', 'acrosome']::text[], '[]'::jsonb),
  ('epithelium-nonkeratinized-cornea', 'Неороговевающий эпителий роговицы', '3. Эпителии', 'Эпителии', 'Роговица глаза', 'Эпителиальная', 'Гематоксилин-эозин', 1, 'Найти многослойный плоский эпителий на поверхности роговицы', 'Базальный слой, шиповатый слой, поверхностный слой клеток', '["Малое увеличение: найти многослойный пласт на поверхности роговицы.","Проверить, что поверхностные клетки имеют ядра — слой неороговевающий.","Различить базальный, шиповатый и поверхностный слои.","Найти базальную мембрану на границе с подлежащей тканью.","Не путать с ороговевающим эпителием кожи: там поверхность без ядер."]'::jsonb, '["Многослойность","Плоские поверхностные клетки","Базальная мембрана","Отсутствие ороговения"]'::jsonb, '["Ядра в клетках всех слоёв","Кератиновые тонофиламенты"]'::jsonb, '["От многослойного ороговевающего (кожи) — в роговице нет рогового слоя"]'::jsonb, '["Принимать эндотелий роговицы за эпителий"]'::jsonb, ARRAY['keratinized-layers', 'basement-membrane', 'nucleus']::text[], '[]'::jsonb),
  ('epithelium-ciliated-trachea', 'Мерцательный эпителий трахеи', '3. Эпителии', 'Эпителии', 'Трахея', 'Эпителиальная', 'Гематоксилин-эозин', 2, 'Найти многорядный мерцательный эпителий на внутренней поверхности трахеи', 'Реснички на апикальной поверхности, бокаловидные клетки, базальные клетки', '["Малое увеличение: найти выстилку слизистой оболочки трахеи.","Различить реснитчатые клетки и бокаловидные (светлые куполки).","Большое увеличение: рассмотреть реснички на апикальной поверхности.","Найти базальную мембрану и подлежащую соединительную ткань.","Проверить, что ядра лежат на разных уровнях — многорядность."]'::jsonb, '["Многорядность","Реснички","Бокаловидные клетки","Ядра на разных уровнях"]'::jsonb, '["Бокаловидные клетки (слизистые гранулы)","Реснички"]'::jsonb, '["От цилиндрического эпителия кишки — многорядность и бокаловидные клетки"]'::jsonb, '["Реснички могут быть плохо видны при слабом увеличении"]'::jsonb, ARRAY['cilia', 'goblet-cells', 'basement-membrane', 'nucleus']::text[], '[]'::jsonb),
  ('epithelium-transitional-bladder', 'Переходный эпителий мочевого пузыря', '3. Эпителии', 'Эпителии', 'Мочевой пузырь', 'Эпителиальная', 'Гематоксилин-эозин', 2, 'Найти слизистую оболочку мочевого пузыря с переходным эпителием', 'Крупные покровные клетки на поверхности, кубические клетки базального слоя', '["Малое увеличение: найти складчатую слизистую оболочку.","Определить покровные клетки крупного размера (иногда двуядерные).","Проверить число слоёв: от 3 до 6–8 в зависимости от растяжения.","Перейти на большое увеличение: крупные округлые ядра, светлая цитоплазма.","Найти в стенке пучки гладкой мышечной ткани — второй объект изучения."]'::jsonb, '["Крупные покровные клетки","Зонтичные клетки на поверхности","Способность к растяжению"]'::jsonb, '["Зонтичные клетки","Гладкая мышечная ткань (здесь же)"]'::jsonb, '["При растяжении переходный эпителий становится тоньше, клетки уплощаются"]'::jsonb, '["В этом препарате также видна гладкая мышечная ткань — не путать"]'::jsonb, ARRAY['urothelium-dome-cells', 'smooth-muscle', 'nucleus']::text[], '[]'::jsonb),
  ('epithelium-columnar-intestine', 'Цилиндрический эпителий тонкой кишки', '3. Эпителии', 'Эпителии', 'Тонкая кишка', 'Эпителиальная', 'Гематоксилин-эозин', 2, 'Найти кишечные ворсинки, покрытые цилиндрическим эпителием', 'Высокие цилиндрические клетки с каймой, бокаловидные клетки', '["Малое увеличение: найти ворсинки тонкой кишки.","Определить однослойный цилиндрический эпителий на поверхности ворсинки.","Найти бокаловидные клетки — светлые расширения среди цилиндрических.","Большое увеличение: рассмотреть щёточную кайму на апикальном полюсе.","Проверить овальные ядра, смещённые к базальному полюсу."]'::jsonb, '["Высокий цилиндрический эпителий","Щёточная кайма","Бокаловидные клетки","Ворсинки"]'::jsonb, '["Микроворсинки","Бокаловидные клетки","Всасывающие клетки"]'::jsonb, '["От цилиндрического эпителия желудка — в тонкой кишке есть щёточная кайма"]'::jsonb, '["Щёточная кайма может быть плохо видна при малом увеличении"]'::jsonb, ARRAY['microvilli-brush-border', 'goblet-cells', 'nucleus']::text[], '[]'::jsonb),
  ('ct-blood-smear', 'Мазок крови', '4. Соединительная ткань', 'Соединительная ткань', 'Кровь', 'Соединительная (жидкая)', 'Романовского-Гимза', 2, 'Найти разные типы клеток крови', 'Эритроциты, лейкоциты (нейтрофилы, лимфоциты, моноциты)', '["Малое увеличение: выбрать участок тонкого мазка, где клетки не накладываются.","Найти преобладающие безъядерные эритроциты.","Найти лейкоциты: крупнее, с ядром и окрашенной цитоплазмой.","Определить тромбоциты — мелкие фиолетовые пластинки между клетками.","Большое увеличение: оценить зернистость и форму ядра лейкоцитов."]'::jsonb, '["Эритроциты (двояковогнутые диски)","Нейтрофилы (сегментированные ядра)","Лимфоциты (круглое ядро)","Моноциты (крупные)"]'::jsonb, '["Гранулы в нейтрофилах","Тромбоциты"]'::jsonb, '["Нейтрофилы — сегментированные ядра, лимфоциты — круглые ядра, моноциты — крупные с бобовидным ядром"]'::jsonb, '["Не путать лимфоциты с эритроцитами"]'::jsonb, ARRAY['erythrocytes', 'leukocytes', 'platelets']::text[], '[]'::jsonb),
  ('ct-hyaline-cartilage', 'Гиалиновый хрящ', '4. Соединительная ткань', 'Соединительная ткань', 'Трахея / Сустав', 'Соединительная (хрящевая)', 'Гематоксилин-эозин', 2, 'Найти участок гиалинового хряща с изогенными группами клеток', 'Хондроциты в лакунах, изогенные группы', '["Малое увеличение: найти базофильное (сине-фиолетовое) межклеточное вещество.","Найти округлые хондроциты в лакунах.","Обратить внимание на изогенные группы (2–4 клетки).","Проверить, что волокна в матриксе не видны — признак гиалинового хряща.","Найти надхрящницу на периферии."]'::jsonb, '["Хондроциты в лакунах","Изогенные группы","Базофильный матрикс","Надхрящница"]'::jsonb, '["Гликоген в хондроцитах","Коллаген II типа (матрикс)"]'::jsonb, '["От эластического хряща — в гиалиновом нет эластических волокон"]'::jsonb, '["Артефакты окрашивания могут имитировать структуру хряща"]'::jsonb, ARRAY['chondrocytes', 'isogenous-groups', 'nucleus']::text[], '[]'::jsonb),
  ('ct-elastic-cartilage', 'Эластический хрящ', '4. Соединительная ткань', 'Соединительная ткань', 'Ушная раковина', 'Соединительная (хрящевая)', 'Орсеин / Гематоксилин-эозин', 3, 'Найти хрящ с сетью эластических волокон', 'Хондроциты в лакунах, сеть эластических волокон между ними', '["Малое увеличение: найти хрящ с сетью тёмных волокон.","Отличить от гиалинового: волокна видны в матриксе.","Найти хондроциты и изогенные группы между волокнами.","Большое увеличение: оценить направление эластических волокон.","Проверить отсутствие крупных пучков коллагена (это не сухожилие)."]'::jsonb, '["Эластические волокна","Хондроциты в лакунах","Сеть волокон в матриксе"]'::jsonb, '["Эластические волокна (окрашиваются орсеином)"]'::jsonb, '["От гиалинового хряща — в эластическом есть эластические волокна"]'::jsonb, '["Эластические волокна тонкие — нужны специальные красители"]'::jsonb, ARRAY['chondrocytes', 'elastic-fibers', 'isogenous-groups']::text[], '[]'::jsonb),
